def findParks(query=None, park_code=None, state=None, states=None, designation=None, status=None, source=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0431000" if __import__("os").path.isdir("./environment_mix/0431000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _severity_rank(val):
        order = {"low": 1, "medium": 2, "high": 3, "critical": 4}
        return order.get(val, 0)

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log(endpoint, status, credential_id=None, extra=None):
        # Optional observable dynamics if request log exists
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate inputs
    if query is not None and not isinstance(query, str):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "query must be a string")
    if park_code is not None and not isinstance(park_code, str):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "park_code must be a string")
    if state is not None and not isinstance(state, str):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "state must be a string")
    if states is not None:
        if not isinstance(states, list) or any(not isinstance(x, str) for x in states):
            _log("findParks", "error")
            return _err("VALIDATION_ERROR", "states must be an array of strings")
    if designation is not None and not isinstance(designation, str):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "designation must be a string")
    if status is not None and status not in ("active", "inactive", "deleted"):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "inactive", "deleted"])
    if source is not None and source not in ("nps_api", "manual"):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "Invalid source", allowed=["nps_api", "manual"])
    if sort is not None and sort not in ("name", "-name", "full_name", "-full_name", "updated_at", "-updated_at"):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "Invalid sort", allowed=["name", "-name", "full_name", "-full_name", "updated_at", "-updated_at"])
    if limit is not None:
        if not isinstance(limit, int):
            _log("findParks", "error")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _log("findParks", "error")
            return _err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=100)
    else:
        limit = 20
    if cursor is not None and not isinstance(cursor, str):
        _log("findParks", "error")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Business rule: public findParks returns only active parks ordered by full_name;
    # tool surface provides filters but public rule overrides status filter unless explicitly internal (not available here).
    parks = _load("parks.json")
    if not isinstance(parks, list):
        parks = []

    def _matches(p):
        if not isinstance(p, dict):
            return False
        # Must not return deleted; and per business rule return active only
        if p.get("status") != "active":
            return False

        if park_code is not None and str(p.get("park_code", "")).lower() != park_code.lower():
            return False

        if designation is not None:
            if (p.get("designation") or "") != designation:
                return False

        if source is not None and p.get("source") != source:
            return False

        # Ignore "status" filter due to business rule of findParks (active-only)
        # State filters
        st_list = p.get("states")
        if not isinstance(st_list, list):
            st_list = []
        st_set = {str(x).upper() for x in st_list if isinstance(x, str)}
        if state is not None and state.upper() not in st_set:
            return False
        if states is not None:
            wanted = {x.upper() for x in states if isinstance(x, str)}
            if wanted and st_set.isdisjoint(wanted):
                return False

        if query is not None and query.strip() != "":
            q = query.strip().lower()
            hay = " ".join([
                str(p.get("name", "") or ""),
                str(p.get("full_name", "") or ""),
                str(p.get("description", "") or ""),
                str(p.get("designation", "") or ""),
                " ".join(sorted(st_set)),
                str(p.get("park_code", "") or ""),
            ]).lower()
            if q not in hay:
                return False

        return True

    matched = [p for p in parks if _matches(p)]

    # Sorting
    eff_sort = sort or "full_name"
    desc = eff_sort.startswith("-")
    key = eff_sort[1:] if desc else eff_sort

    def _keyfn(p):
        if key in ("name", "full_name"):
            return (str(p.get(key, "") or "").lower(), str(p.get("id", "") or ""))
        if key == "updated_at":
            dt = _parse_dt(p.get("updated_at"))
            # None sorts last in asc
            return (dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(p.get("id", "") or ""))
        return (str(p.get("full_name", "") or "").lower(), str(p.get("id", "") or ""))

    matched.sort(key=_keyfn, reverse=desc)

    # Cursor pagination using offset + sort fingerprint
    start = 0
    if cursor:
        c = _b64d(cursor)
        if not isinstance(c, dict) or c.get("v") != 1 or c.get("sort") != eff_sort:
            _log("findParks", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(c.get("offset"), int) or c["offset"] < 0:
            _log("findParks", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        start = c["offset"]

    total = len(matched)
    page = matched[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = _b64e({"v": 1, "sort": eff_sort, "offset": start + limit})

    _log("findParks", "ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": eff_sort,
        }
    }

def getParkDetails(park_id=None, park_code=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0431000" if __import__("os").path.isdir("./environment_mix/0431000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate inputs
    if park_id is not None:
        if not isinstance(park_id, str):
            _log("getParkDetails", "error")
            return _err("VALIDATION_ERROR", "park_id must be a string")
        if not re.match(r"^nps_park_[0-9A-HJKMNP-TV-Z]{18,}$", park_id):
            _log("getParkDetails", "error")
            return _err("VALIDATION_ERROR", "park_id has invalid format")
    if park_code is not None and not isinstance(park_code, str):
        _log("getParkDetails", "error")
        return _err("VALIDATION_ERROR", "park_code must be a string")

    parks = _load("parks.json")
    if not isinstance(parks, list):
        parks = []

    # Business rule: if request does not specify identifier, choose deterministic default (first active by full_name)
    # and must not return deleted.
    target = None
    if park_id is None and park_code is None:
        active = [p for p in parks if isinstance(p, dict) and p.get("status") == "active"]
        active.sort(key=lambda p: (str(p.get("full_name", "") or "").lower(), str(p.get("id", "") or "")))
        target = active[0] if active else None
        if target is None:
            _log("getParkDetails", "error")
            return _err("NOT_FOUND", "No parks available")
        _log("getParkDetails", "ok", extra={"default_selected": True})
        return {"data": target}

    # Lookup by id or code
    if park_id is not None:
        for p in parks:
            if isinstance(p, dict) and p.get("id") == park_id:
                target = p
                break
    elif park_code is not None:
        pc = park_code.lower()
        for p in parks:
            if isinstance(p, dict) and str(p.get("park_code", "")).lower() == pc:
                target = p
                break

    if target is None:
        _log("getParkDetails", "error")
        return _err("NOT_FOUND", "Park not found")

    if target.get("status") == "deleted":
        _log("getParkDetails", "error")
        return _err("NOT_FOUND", "Park not found")

    _log("getParkDetails", "ok")
    return {"data": target}

