    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _sev_rank(val):
        return {"low": 1, "medium": 2, "high": 3, "critical": 4}.get(val, 0)

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _log(endpoint, status_s, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_s,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now(),
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate
    if park_id is not None:
        if not isinstance(park_id, str):
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "park_id must be a string")
        if not re.match(r"^nps_park_[0-9A-HJKMNP-TV-Z]{18,}$", park_id):
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "park_id has invalid format")
    if park_code is not None and not isinstance(park_code, str):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "park_code must be a string")
    if category is not None and category not in ("closure", "hazard", "information", "caution", "weather", "other"):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "Invalid category")
    if severity is not None and severity not in ("low", "medium", "high", "critical"):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "Invalid severity")
    if status is not None and status not in ("active", "expired", "retracted"):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "Invalid status")
    eff_dt = None
    if effective_at is not None:
        if not isinstance(effective_at, str):
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "effective_at must be an ISO 8601 string")
        eff_dt = _parse_dt(effective_at)
        if eff_dt is None:
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "effective_at is malformed")
    if sort is not None and sort not in ("effective_start", "-effective_start", "severity", "-severity", "updated_at", "-updated_at"):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "Invalid sort")
    if limit is not None:
        if not isinstance(limit, int):
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=100)
    else:
        limit = 20
    if cursor is not None and not isinstance(cursor, str):
        _log("getAlerts", "error")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    parks = _load("parks.json")
    if not isinstance(parks, list):
        parks = []
    alerts = _load("alerts.json")
    if not isinstance(alerts, list):
        alerts = []

    # Resolve park if specified
    park = None
    if park_id is not None or park_code is not None:
        if park_id is not None:
            park = next((p for p in parks if isinstance(p, dict) and p.get("id") == park_id), None)
        else:
            pc = park_code.lower()
            park = next((p for p in parks if isinstance(p, dict) and str(p.get("park_code", "")).lower() == pc), None)
        if park is None:
            _log("getAlerts", "error")
            return _err("NOT_FOUND", "Park not found")
        # public requires active park
        if park.get("status") != "active":
            _log("getAlerts", "ok")
            return {"data": [], "meta": {"total": 0, "limit": limit, "cursor": cursor, "next_cursor": None, "has_more": False, "sort": (sort or "-effective_start")}}

    active_park_ids = {p.get("id") for p in parks if isinstance(p, dict) and p.get("status") == "active"}

    # Business rule: return only alerts where park active and alert active; ignore requested status unless internal/debug (not available)
    def _is_effective(a):
        if eff_dt is None:
            return True
        sdt = _parse_dt(a.get("effective_start"))
        edt = _parse_dt(a.get("effective_end"))
        if sdt and eff_dt < sdt:
            return False
        if edt and eff_dt > edt:
            return False
        return True

    def _matches(a):
        if not isinstance(a, dict):
            return False
        pid = a.get("park_id")
        if pid not in active_park_ids:
            return False
        if park is not None and pid != park.get("id"):
            return False
        # public: active only
        if a.get("status") != "active":
            return False
        if category is not None and a.get("category") != category:
            return False
        if severity is not None and a.get("severity") != severity:
            return False
        # ignore requested status due to public rule
        if not _is_effective(a):
            return False
        return True

    matched = [a for a in alerts if _matches(a)]

    eff_sort = sort or "-effective_start"
    desc = eff_sort.startswith("-")
    key = eff_sort[1:] if desc else eff_sort

    def _keyfn(a):
        if key == "effective_start":
            dt = _parse_dt(a.get("effective_start"))
            # None sorts last in asc, first in desc (by using min/max)
            base = dt or (datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if not desc else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc))
            return (base, str(a.get("id", "") or ""))
        if key == "updated_at":
            dt = _parse_dt(a.get("updated_at"))
            base = dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (base, str(a.get("id", "") or ""))
        if key == "severity":
            return (_sev_rank(a.get("severity")), str(a.get("id", "") or ""))
        return (_parse_dt(a.get("effective_start")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(a.get("id", "") or ""))

    matched.sort(key=_keyfn, reverse=desc)

    start = 0
    if cursor:
        c = _b64d(cursor)
        if not isinstance(c, dict) or c.get("v") != 1 or c.get("sort") != eff_sort:
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(c.get("offset"), int) or c["offset"] < 0:
            _log("getAlerts", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        start = c["offset"]

    total = len(matched)
    page = matched[start:start + limit]
    has_more = start + limit < total
    next_cursor = _b64e({"v": 1, "sort": eff_sort, "offset": start + limit}) if has_more else None

    _log("getAlerts", "ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": eff_sort,
        }
    }

