    if park_id is not None or park_code is not None:
        if park_id is not None:
            park = next((p for p in parks if isinstance(p, dict) and p.get("id") == park_id), None)
        else:
            pc = park_code.lower()
            park = next((p for p in parks if isinstance(p, dict) and str(p.get("park_code", "")).lower() == pc), None)
        if park is None:
            _log("getVisitorCenters", "error")
            return _err("NOT_FOUND", "Park not found")
        if park.get("status") != "active":
            _log("getVisitorCenters", "ok")
            return {"data": [], "meta": {"total": 0, "limit": limit, "cursor": cursor, "next_cursor": None, "has_more": False, "sort": (sort or "name")}}

    active_park_ids = {p.get("id") for p in parks if isinstance(p, dict) and p.get("status") == "active"}

    allowed_public_status = {"open", "seasonal", "closed"}  # exclude inactive
    def _matches(v):
        if not isinstance(v, dict):
            return False
        pid = v.get("park_id")
        if pid not in active_park_ids:
            return False
        if park is not None and pid != park.get("id"):
            return False
        st = v.get("status")
        if st not in allowed_public_status:
            return False
        if status is not None:
            # If caller asks for inactive, public must exclude -> empty set (not error)
            if status == "inactive":
                return False
            if st != status:
                return False
        return True

    matched = [v for v in vcs if _matches(v)]

    eff_sort = sort or "name"
    desc = eff_sort.startswith("-")
    key = eff_sort[1:] if desc else eff_sort

    def _keyfn(v):
        if key == "name":
            return (str(v.get("name", "") or "").lower(), str(v.get("id", "") or ""))
        if key == "updated_at":
            dt = _parse_dt(v.get("updated_at"))
            return (dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(v.get("id", "") or ""))
        return (str(v.get("name", "") or "").lower(), str(v.get("id", "") or ""))

    matched.sort(key=_keyfn, reverse=desc)

    start = 0
    if cursor:
        c = _b64d(cursor)
        if not isinstance(c, dict) or c.get("v") != 1 or c.get("sort") != eff_sort:
            _log("getVisitorCenters", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(c.get("offset"), int) or c["offset"] < 0:
            _log("getVisitorCenters", "error")
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        start = c["offset"]

    total = len(matched)
    page = matched[start:start + limit]
    has_more = start + limit < total
    next_cursor = _b64e({"v": 1, "sort": eff_sort, "offset": start + limit}) if has_more else None

    _log("getVisitorCenters", "ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": eff_sort,
        }
    }

