            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in allowed_status:
            _log("VALIDATION_ERROR", "status must be one of: open, seasonal, closed, inactive")
            return _err("VALIDATION_ERROR", "status must be one of: open, seasonal, closed, inactive")

    allowed_sort = ("name", "-name", "updated_at", "-updated_at")
    if sort is None:
