            _log("VALIDATION_ERROR", "sort must be a string")
            return _err("VALIDATION_ERROR", "sort must be a string")
        if sort not in allowed_sort:
            _log("VALIDATION_ERROR", "sort must be one of: name, -name, updated_at, -updated_at")
            return _err("VALIDATION_ERROR", "sort must be one of: name, -name, updated_at, -updated_at")

    if limit is None:
        limit = 20
    else:
        if not isinstance(limit, int):
            _log("VALIDATION_ERROR", "limit must be an integer")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 100:
            _log("VALIDATION_ERROR", "limit must be between 1 and 100")
