        parks = []
    if not isinstance(campgrounds, list):
        campgrounds = []

    parks_by_id = {p.get("id"): p for p in parks if isinstance(p, dict) and isinstance(p.get("id"), str)}
    parks_by_code = {}
    for p in parks:
        if isinstance(p, dict):
            pc = p.get("park_code")
            if isinstance(pc, str):
                parks_by_code[pc.lower()] = p

    # ---- resolve park scope ----
    resolved_park = None
    if park_id is not None:
        resolved_park = parks_by_id.get(park_id)
        if not resolved_park:
            _log("NOT_FOUND", "park_id did not resolve to a park")
            return _err("NOT_FOUND", "park_id did not resolve to a park")
    if resolved_park is None and park_code is not None:
        resolved_park = parks_by_code.get(park_code.lower())
        if not resolved_park:
            _log("NOT_FOUND", "park_code did not resolve to a park")
            return _err("NOT_FOUND", "park_code did not resolve to a park")

    # Public rule: join to parks where parks.status='active'; exclude inactive campgrounds
    active_park_ids = {p.get("id") for p in parks if isinstance(p, dict) and p.get("status") == "active" and isinstance(p.get("id"), str)}

    if resolved_park is not None and resolved_park.get("status") != "active":
        # The park exists but is not eligible for public join; behave as not found for public endpoint
        _log("NOT_FOUND", "park is not available")
        return _err("NOT_FOUND", "park is not available")

    allowed_public_cg_status = {"open", "seasonal", "closed"}  # exclude 'inactive'

    filtered = []
    for cg in campgrounds:
        if not isinstance(cg, dict):
            continue
        pid = cg.get("park_id")
        if not isinstance(pid, str):
            continue
        if pid not in active_park_ids:
            continue
        if resolved_park is not None and pid != resolved_park.get("id"):
            continue

        cg_status = cg.get("status")
        if cg_status not in allowed_public_cg_status:
            continue
        if status is not None and cg_status != status:
            continue

        filtered.append(cg)

    # ---- sorting ----
    def _dt_key(v):
        if not isinstance(v, str) or not v:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    reverse = sort.startswith("-")
    sort_field = sort[1:] if reverse else sort
    if sort_field == "name":
        filtered.sort(key=lambda r: (str(r.get("name") or "").casefold(), str(r.get("id") or "")), reverse=reverse)
    else:  # updated_at
        filtered.sort(key=lambda r: (_dt_key(r.get("updated_at")), str(r.get("id") or "")), reverse=reverse)

    # ---- cursor pagination (cursor is last seen id in the sorted list) ----
    start_idx = 0
    if cursor:
        # find first element strictly after cursor id
        for i, row in enumerate(filtered):
            if row.get("id") == cursor:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = start_idx + limit < len(filtered)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    _log("OK", None, cursor_out=next_cursor)
    return {
        "campgrounds": page,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

