            return _err("VALIDATION_ERROR", "status must be one of: scheduled, cancelled, completed, inactive")

    if category is not None and not isinstance(category, str):
        _log("VALIDATION_ERROR", "category must be a string")
        return _err("VALIDATION_ERROR", "category must be a string")

    start_after_dt, err = _parse_dt(start_after, "start_after")
    if err:
        _log("VALIDATION_ERROR", err["error"]["message"])
        return err
    start_before_dt, err = _parse_dt(start_before, "start_before")
    if err:
        _log("VALIDATION_ERROR", err["error"]["message"])
        return err

    allowed_sort = ("start_at", "-start_at", "updated_at", "-updated_at")
    if sort is None:
        sort = "start_at"
    else:
        if not isinstance(sort, str):
            _log("VALIDATION_ERROR", "sort must be a string")
            return _err("VALIDATION_ERROR", "sort must be a string")
