        parks = []
    if not isinstance(events, list):
        events = []

    parks_by_id = {p.get("id"): p for p in parks if isinstance(p, dict) and isinstance(p.get("id"), str)}
    parks_by_code = {}
    for p in parks:
        if isinstance(p, dict):
            pc = p.get("park_code")
            if isinstance(pc, str):
                parks_by_code[pc.lower()] = p

    resolved_park = None
