            continue
        if start_after_dt is not None and ev_start < start_after_dt:
            continue
        if start_before_dt is not None and ev_start > start_before_dt:
            continue

        filtered.append(ev)

    def _dt_key(v):
        dtv = _dt(v)
        if dtv is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dtv

    reverse = sort.startswith("-")
    sort_field = sort[1:] if reverse else sort
    if sort_field == "start_at":
        filtered.sort(key=lambda r: (_dt_key(r.get("start_at")), str(r.get("id") or "")), reverse=reverse)
